    /// Agent and machine states, each with an SF Symbol and a colour.
    enum Status: String, CaseIterable, Sendable {
        case working
        case blocked
        case done
        case idle
        case off
        case connected
        case connecting
        case reconnecting
        case error

        /// SF Symbol name for the state's icon.
        var symbol: String {
            switch self {
            case .working: "azulejo.ring"
            case .blocked: "exclamationmark.circle.fill"
            case .done: "checkmark.circle"
            case .idle: "circle.dashed"
            case .off: "circle.dotted"
            case .connected: "circle.fill"
            case .connecting: "circle.dotted"
            case .reconnecting: "arrow.triangle.2.circlepath"
            case .error: "exclamationmark.triangle.fill"
            }
        }

        var color: NSColor {
            switch self {
            case .working: Design.Color.statusWorking
            case .blocked: Design.Color.statusBlocked
            case .done: Design.Color.statusDone
            case .idle: Design.Color.statusIdle
            case .off: Design.Color.statusOff
            case .connected: Design.Color.statusConnected
            case .connecting: Design.Color.statusConnecting
            case .reconnecting: Design.Color.statusReconnecting
            case .error: Design.Color.statusError
            }
        }
    }

    enum StatusIcon {
        /// The state's symbol and colour.
        static func `for`(_ status: Status) -> (symbol: String, color: NSColor) {
            (status.symbol, status.color)
        }

        /// The state's symbol as a tinted image, or nil if the symbol is missing.
        /// Its colour is resolved now, in the theme's appearance: the image is
        /// often baked into a layer (StatusIconView makes it again per theme).
        /// Symbols named `azulejo.*` are drawn by the app (DesignSupport.swift).
        static func image(_ status: Status, pointSize: CGFloat = 11) -> NSImage? {
            if status.symbol.hasPrefix("azulejo.") {
                return Design.customSymbol(status.symbol, color: status.color, pointSize: pointSize)
            }
            let config = NSImage.SymbolConfiguration(pointSize: pointSize, weight: .regular)
                .applying(.init(paletteColors: [Theme.resolved(status.color)]))
            return NSImage(systemSymbolName: status.symbol, accessibilityDescription: status.rawValue)?
                .withSymbolConfiguration(config)
        }
    }

